INSERT INTO dump_descriptions (base_key, description) VALUES ('fsd-windowsnoeditor提高帧数-去除贴花_p', 'Disables dozens of decal materials, including bullet impacts, bug splats, fire, corrosion, puddles, footprints, and Scorched Earth.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fsd-windowsnoeditor提高帧率-去除岩痘粒子，可见死亡毒物、岩痘虫轨迹弹道', 'Removes many Rockpox and plague particle effects, including spores, impacts, tendrils, larva effects, and projectile visuals.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('miscoptimizations', 'Shortens draw distances for Refinery and Minehead equipment, flares and the Flare Gun, Goo Cannon puddles, and assorted cave hazards and props.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('u39更多敌人简化模型(单删看守着)', 'Replaces a broad set of enemy and cave-creature skeletal meshes with simplified models, including leeches, jellyfish, plants, woodlice, and spiders.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('dea_a02', 'Adds custom enemy variants including Glasher, colored and stagger Spitters, new Shooters and Mactera, Trundle, Grooter, Fanatic, Sprout, and Stabber Vine.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
